from pyspark.sql import functions as F


def with_fact(df, name, value):
    # Adds a column called name holding the same value on every row.
    return df.withColumn(name, F.lit(value))


def solve(orders):
    delivered = orders.filter(F.col("status") == "delivered")
    # Add the second filter, keep two columns, then count the Filter steps.
    return with_fact(delivered, "filter_steps", 0)
